import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './views/Dashboard';
import PracticeView from './views/PracticeView';
import ActiveExam from './views/ActiveExam';
import ResultsView from './views/ResultsView';
import ExamHubView from './views/ExamHubView';
import ExamHistoryView from './views/ExamHistoryView';
import { geminiService } from './services/geminiService';
import { Subject, QuestionType, ExamSession, GradingResult, Language, UserProfile, SessionHistory, UserGoals, Department } from './types';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState('dashboard');
  const [isLoading, setIsLoading] = useState(false);
  const [activeSession, setActiveSession] = useState<ExamSession | null>(null);
  const [gradingResults, setGradingResults] = useState<GradingResult[] | null>(null);
  const [sessionAnswers, setSessionAnswers] = useState<Record<string, any>>({});

  const [userProfile, setUserProfile] = useState<UserProfile>(() => {
    const saved = localStorage.getItem('mrab_profile');
    return saved ? JSON.parse(saved) : { 
      department: Department.HUMANITIES, // Defaulting to Humanities since Settings is removed
      goals: { topicsMastered: 20, studyHours: 50, targetAccuracy: 80 }
    };
  });

  const [sessionHistory, setSessionHistory] = useState<SessionHistory[]>(() => {
    const saved = localStorage.getItem('mrab_history');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('mrab_profile', JSON.stringify(userProfile));
  }, [userProfile]);

  useEffect(() => {
    localStorage.setItem('mrab_history', JSON.stringify(sessionHistory));
  }, [sessionHistory]);

  const startPractice = async (subject: Subject, chapter: string, type: QuestionType, count: number, language: Language) => {
    setIsLoading(true);
    try {
      let questions = [];
      if (type === 'MCQ') {
        questions = await geminiService.generateMCQs(subject, chapter, count, language);
      } else {
        const cq = await geminiService.generateCQ(subject, chapter, language);
        if (cq) questions = [cq];
      }

      if (questions.length > 0) {
        const newSession: ExamSession = {
          id: Math.random().toString(36).substring(7),
          subject,
          mode: 'Practice',
          startTime: Date.now(),
          questions,
          durationMinutes: type === 'MCQ' ? Math.max(5, count * 1) : 30,
          isCompleted: false,
          language
        };
        setActiveSession(newSession);
        setActiveView('active-exam');
      }
    } catch (error) {
      console.error("Start Practice Error:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const startBoardExam = async (subject: Subject, language: Language) => {
    setIsLoading(true);
    try {
      const { mcqs, cqs } = await geminiService.generateFullExam(subject, language);
      const allQuestions = [...mcqs, ...cqs];

      if (allQuestions.length > 0) {
        const newSession: ExamSession = {
          id: Math.random().toString(36).substring(7),
          subject,
          mode: 'BOARD',
          startTime: Date.now(),
          questions: allQuestions,
          durationMinutes: 120, // 2 hours for board mock
          isCompleted: false,
          language
        };
        setActiveSession(newSession);
        setActiveView('active-exam');
      }
    } catch (error) {
      console.error("Start Board Exam Error:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleFinishExam = async (answers: Record<string, any>) => {
    if (!activeSession) return;
    setSessionAnswers(answers);
    setIsLoading(true);

    try {
      const results: GradingResult[] = [];
      for (const q of activeSession.questions) {
        if (q.type === 'MCQ') {
          const isCorrect = answers[q.id] === q.correctOptionId;
          const fb = activeSession.language === 'bn' 
            ? (isCorrect ? 'অসাধারণ! ধারণাটি পরিষ্কার।' : `সঠিক উত্তর: ${q.options.find(o => o.id === q.correctOptionId)?.text}।`)
            : (isCorrect ? 'Excellent! Concept is clear.' : `Correct answer: ${q.options.find(o => o.id === q.correctOptionId)?.text}.`);

          results.push({
            questionId: q.id,
            obtainedMarks: isCorrect ? 1 : 0,
            maxMarks: 1,
            feedback: fb,
            status: isCorrect ? 'Correct' : 'Incorrect'
          });
        } else {
          const cqResult = await geminiService.gradeCQAnswer(q, answers[q.id] || {}, activeSession.language);
          results.push(...cqResult);
        }
      }

      const obtained = results.reduce((acc, r) => acc + r.obtainedMarks, 0);
      const total = results.reduce((acc, r) => acc + r.maxMarks, 0);
      const accuracy = Math.round((obtained / total) * 100) || 0;

      const historyEntry: SessionHistory = {
        sessionId: activeSession.id,
        subject: activeSession.subject,
        timestamp: Date.now(),
        score: obtained,
        totalMarks: total,
        accuracy: accuracy,
        durationMinutes: activeSession.durationMinutes,
        mode: activeSession.mode
      };

      setSessionHistory(prev => [...prev, historyEntry]);
      setGradingResults(results);
      setActiveView('results');
    } catch (error) {
      console.error("Grading Error:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleUpdateGoals = (newGoals: UserGoals) => {
    setUserProfile(prev => ({ ...prev, goals: newGoals }));
  };

  const renderView = () => {
    switch (activeView) {
      case 'dashboard':
        return (
          <Dashboard 
            onStartPractice={() => setActiveView('practice')} 
            onGoToExams={() => setActiveView('exams')}
            profile={userProfile}
            history={sessionHistory}
            onUpdateGoals={handleUpdateGoals}
          />
        );
      case 'practice':
        return <PracticeView onStart={startPractice} isLoading={isLoading} />;
      case 'exams':
        return <ExamHubView onStartExam={startBoardExam} onGoToHistory={() => setActiveView('exam-history')} isLoading={isLoading} />;
      case 'exam-history':
        return <ExamHistoryView history={sessionHistory} onBack={() => setActiveView('exams')} />;
      case 'active-exam':
        return activeSession ? (
          <ActiveExam session={activeSession} onFinish={handleFinishExam} isGrading={isLoading} />
        ) : null;
      case 'results':
        return activeSession && gradingResults ? (
          <ResultsView 
            questions={activeSession.questions} 
            answers={sessionAnswers}
            results={gradingResults}
            onBack={() => {
              setActiveView('dashboard');
              setActiveSession(null);
            }}
          />
        ) : null;
      default:
        return (
          <Dashboard 
            onStartPractice={() => setActiveView('practice')} 
            onGoToExams={() => setActiveView('exams')}
            profile={userProfile}
            history={sessionHistory}
            onUpdateGoals={handleUpdateGoals}
          />
        );
    }
  };

  return (
    <Layout activeView={activeView} onNavigate={setActiveView}>
      {renderView()}
    </Layout>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { MCQQuestion, CQQuestion, Subject, GradingResult, Language } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const CORE_BOARD_INSTRUCTIONS = `
STRICT COMPLIANCE: Bangladesh NCTB SSC Board Pattern (Short Syllabus 2026).
QUESTION STYLES:
1. MCQs must include:
   - Simple Recall (Direct facts).
   - Multiple Completion (i, ii, iii statements; Options: A. i & ii, B. ii & iii, etc.).
   - Situation-based (Small stem followed by 2 questions).
2. Creative Questions (CQ):
   - (ক) Knowledge: Direct textbook fact.
   - (খ) Comprehension: Explain 'why' or 'how' a concept works.
   - (গ) Application: Apply textbook concept to the provided Stimulus (উদ্দীপক).
   - (ঘ) Higher Order: Critical analysis/evaluation of the situation.
`;

const SUBJECT_PROMPTS = {
  [Subject.BANGLA_1ST]: `
    - CQ Stem: Must be a short poem snippet or a unique scenario reflecting textbook themes.
    - Part (ক): Author's name, publication year, or direct fact.
    - Part (খ): Deep meaning of a specific line.
  `,
  [Subject.HISTORY]: `
    - CQ Stem: Use modern-day analogies to historical events. 
    - Example: A village leader's behavior mirroring a Mughal Emperor or a British Governor.
    - Topics: Ancient/Medieval Bengal, 1970 Elections, Liberation War.
  `,
  [Subject.MATH]: `
    - MCQ: Include property-based questions and calculation-based.
    - CQ Stem: Real-world scenario (e.g., area of a garden, age of father/son) leading to equations.
  `,
  [Subject.ENGLISH_1ST]: `
    - MCQ: Synonyms, Antonyms, and inference from seen passages.
    - Writing: Formal/Informal letters, Paragraphs, Graphs/Charts.
  `
};

export const geminiService = {
  async generateMCQs(subject: Subject, chapter: string, count: number, language: Language): Promise<MCQQuestion[]> {
    const isEnglishSubject = subject === Subject.ENGLISH_1ST || subject === Subject.ENGLISH_2ND;
    const effectiveLanguage = isEnglishSubject ? 'en' : language;
    const specificPrompt = SUBJECT_PROMPTS[subject as keyof typeof SUBJECT_PROMPTS] || "";

    const langPrompt = effectiveLanguage === 'bn' 
      ? "Questions and explanations MUST be in Bengali (বাংলা ভাষা). Use standard board terminology." 
      : "Questions and explanations MUST be in English.";

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `${CORE_BOARD_INSTRUCTIONS}
      Subject: ${subject}
      Topic: ${chapter}
      ${specificPrompt}
      ACTION: Generate exactly ${count} Board-style Multiple Choice Questions (MCQs).
      STRICT RULE: DO NOT include any Creative Questions (CQ), Stimulus (উদ্দীপক), or written response parts.
      Important: Ensure at least 30% are 'Multiple Completion' type (i, ii, iii statements).
      ${langPrompt}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              type: { type: Type.STRING, description: "Must be 'MCQ' only." },
              chapter: { type: Type.STRING },
              question: { type: Type.STRING, description: "Include i, ii, iii statements here if it's a multiple completion type." },
              options: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    id: { type: Type.STRING },
                    text: { type: Type.STRING }
                  },
                  required: ["id", "text"]
                }
              },
              correctOptionId: { type: Type.STRING },
              explanation: { type: Type.STRING },
              difficulty: { type: Type.STRING }
            },
            required: ["id", "type", "chapter", "question", "options", "correctOptionId", "explanation"]
          }
        }
      }
    });

    try {
      const questions: MCQQuestion[] = JSON.parse(response.text || '[]');
      // Safety filter to ensure we only have MCQs and exact count
      return questions
        .filter(q => q.type === 'MCQ')
        .slice(0, count);
    } catch (e) {
      console.error("Failed to parse MCQs", e);
      return [];
    }
  },

  async generateCQ(subject: Subject, chapter: string, language: Language): Promise<CQQuestion | null> {
    const isEnglishSubject = subject === Subject.ENGLISH_1ST || subject === Subject.ENGLISH_2ND;
    const effectiveLanguage = isEnglishSubject ? 'en' : language;
    const specificPrompt = SUBJECT_PROMPTS[subject as keyof typeof SUBJECT_PROMPTS] || "";

    const langPrompt = effectiveLanguage === 'bn' 
      ? "Content MUST be in Bengali (বাংলা ভাষা)." 
      : "Content MUST be in English.";

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `${CORE_BOARD_INSTRUCTIONS}
      Subject: ${subject}
      Topic: ${chapter}
      ${specificPrompt}
      Generate a HIGH QUALITY Board Standard Creative Question (CQ) with a high-quality stimulus (উদ্দীপক).
      ${langPrompt}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            id: { type: Type.STRING },
            type: { type: Type.STRING, description: "Must be 'CQ' only." },
            chapter: { type: Type.STRING },
            stem: { type: Type.STRING, description: "The Stimulus (উদ্দীপক) in 4-6 sentences." },
            parts: {
              type: Type.OBJECT,
              properties: {
                a: { 
                  type: Type.OBJECT, 
                  properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } },
                  required: ["question", "marks", "label"]
                },
                b: { 
                  type: Type.OBJECT, 
                  properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } },
                  required: ["question", "marks", "label"]
                },
                c: { 
                  type: Type.OBJECT, 
                  properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } },
                  required: ["question", "marks", "label"]
                },
                d: { 
                  type: Type.OBJECT, 
                  properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } },
                  required: ["question", "marks", "label"]
                }
              },
              required: ["a", "b", "c", "d"]
            }
          },
          required: ["id", "type", "chapter", "stem", "parts"]
        }
      }
    });

    try {
      return JSON.parse(response.text || 'null');
    } catch (e) {
      console.error("Failed to parse CQ", e);
      return null;
    }
  },

  async generateFullExam(subject: Subject, language: Language): Promise<{ mcqs: MCQQuestion[], cqs: CQQuestion[] }> {
    const mcqs = await this.generateMCQs(subject, "Syllabus 2026", 30, language);
    const cqs: CQQuestion[] = [];
    const cqPromises = Array(4).fill(null).map((_, i) => 
      this.generateCQ(subject, `Board Pattern Set ${i+1}`, language)
    );
    const resolvedCqs = await Promise.all(cqPromises);
    resolvedCqs.forEach(cq => { if(cq) cqs.push(cq); });
    return { mcqs, cqs };
  },

  async gradeCQAnswer(question: CQQuestion, answers: Record<string, { text: string, image?: string }>, language: Language): Promise<GradingResult[]> {
    const isEnglishSubject = question.stem.toLowerCase().includes('english') || (question.chapter && question.chapter.toLowerCase().includes('english'));
    const effectiveLanguage = isEnglishSubject ? 'en' : language;
    const langPrompt = effectiveLanguage === 'bn' ? "Feedback in Bengali." : "Feedback in English.";

    const parts: any[] = [{ text: `Strictly grade this answer following the NCTB SSC Board Marking Policy. 
    Consider clarity, terminology, and how well the student related (c) and (d) to the stem. ${langPrompt}` }];

    (['a', 'b', 'c', 'd'] as const).forEach(p => {
      const qPart = question.parts[p];
      if (qPart) {
        const ans = answers[p] || { text: '' };
        parts.push({ text: `Part ${p.toUpperCase()} (${qPart.marks} marks): ${qPart.question}\nStudent Answer: ${ans.text || '[Image/Empty]'}` });
        if (ans.image) {
          parts.push({ inlineData: { data: ans.image.split(',')[1], mimeType: 'image/jpeg' } });
        }
      }
    });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              questionId: { type: Type.STRING },
              obtainedMarks: { type: Type.NUMBER },
              maxMarks: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              status: { type: Type.STRING }
            },
            required: ["questionId", "obtainedMarks", "maxMarks", "feedback", "status"]
          }
        }
      }
    });

    try {
      return JSON.parse(response.text || '[]');
    } catch (e) {
      console.error("Failed to parse grading", e);
      return [];
    }
  }
};

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './views/Dashboard';
import PracticeView from './views/PracticeView';
import ActiveExam from './views/ActiveExam';
import ResultsView from './views/ResultsView';
import ExamHubView from './views/ExamHubView';
import ExamHistoryView from './views/ExamHistoryView';
import { geminiService } from './services/geminiService';
import { Subject, QuestionType, ExamSession, GradingResult, Language, UserProfile, SessionHistory, UserGoals, Department } from './types';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState('dashboard');
  const [isLoading, setIsLoading] = useState(false);
  const [activeSession, setActiveSession] = useState<ExamSession | null>(null);
  const [gradingResults, setGradingResults] = useState<GradingResult[] | null>(null);
  const [sessionAnswers, setSessionAnswers] = useState<Record<string, any>>({});

  const [userProfile, setUserProfile] = useState<UserProfile>(() => {
    const saved = localStorage.getItem('mrab_profile');
    return saved ? JSON.parse(saved) : { 
      department: Department.HUMANITIES, // Defaulting to Humanities since Settings is removed
      goals: { topicsMastered: 20, studyHours: 50, targetAccuracy: 80 }
    };
  });

  const [sessionHistory, setSessionHistory] = useState<SessionHistory[]>(() => {
    const saved = localStorage.getItem('mrab_history');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('mrab_profile', JSON.stringify(userProfile));
  }, [userProfile]);

  useEffect(() => {
    localStorage.setItem('mrab_history', JSON.stringify(sessionHistory));
  }, [sessionHistory]);

  const startPractice = async (subject: Subject, chapter: string, type: QuestionType, count: number, language: Language) => {
    setIsLoading(true);
    try {
      let questions = [];
      if (type === 'MCQ') {
        const mcqs = await geminiService.generateMCQs(subject, chapter, count, language);
        // Strict filtering to ensure only requested MCQ type is present
        questions = mcqs.filter(q => q.type === 'MCQ').slice(0, count);
      } else {
        const cq = await geminiService.generateCQ(subject, chapter, language);
        if (cq && cq.type === 'CQ') questions = [cq];
      }

      if (questions.length > 0) {
        const newSession: ExamSession = {
          id: Math.random().toString(36).substring(7),
          subject,
          mode: 'Practice',
          startTime: Date.now(),
          questions,
          durationMinutes: type === 'MCQ' ? Math.max(5, count * 1) : 30,
          isCompleted: false,
          language
        };
        setActiveSession(newSession);
        setActiveView('active-exam');
      }
    } catch (error) {
      console.error("Start Practice Error:", error);
    } finally {
      setIsLoading(false);
    }
  };

