        </div>

        {/* Input Area */}
        <div className="p-4 bg-slate-900/50 border-t border-slate-800">
          {attachedImage && (
            <div className="mb-4 relative inline-block">
              <img src={attachedImage} alt="Preview" className="h-20 w-20 object-cover rounded-xl border-2 border-indigo-500" />
              <button 
                onClick={() => setAttachedImage(null)}
                className="absolute -top-2 -right-2 bg-red-600 text-white p-1 rounded-full shadow-lg"
              >
                <X size={12} />
              </button>
            </div>
          )}

          <div className="flex items-center gap-2">
            <input 
              type="file" 
              accept="image/*" 
              className="hidden" 
              ref={fileInputRef}
              onChange={(e) => {
                const file = e.target.files?.[0];
                if (file) handleImageUpload(file);
              }}
            />
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="p-3 bg-slate-800 text-slate-400 hover:text-white rounded-2xl transition-all border border-slate-700"
            >
              <Camera size={20} />
            </button>

            <div className="flex-1 relative">
              <input 
                type="text"
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                placeholder="আপনার প্রশ্ন এখানে লিখুন..."
                className="w-full bg-slate-950 border border-slate-800 rounded-2xl pl-5 pr-12 py-3.5 text-slate-200 focus:outline-none focus:border-indigo-500 transition-all text-sm"
              />
              <button 
                onClick={() => handleSendMessage()}
                disabled={isTyping || (!inputText.trim() && !attachedImage)}
                className="absolute right-2 top-1/2 -translate-y-1/2 p-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl transition-all disabled:opacity-30"
              >
                <Send size={18} />
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AITutorView;

