}

export enum Department {
  SCIENCE = 'Science (বিজ্ঞান)',
  HUMANITIES = 'Humanities (মানবিক)',
  COMMERCE = 'Business Studies (ব্যবসায় শিক্ষা)'
}

export interface UserGoals {
  topicsMastered: number;
  studyHours: number;
  targetAccuracy: number;
}

export interface UserProfile {
  department: Department | '';
  goals: UserGoals;
}

export type Language = 'bn' | 'en';

export interface SyllabusItem {
  id: string;
  subject: Subject;
  chapterNumber: number;
  chapterTitle: string;
  topics: string[];
}

export type QuestionType = 'MCQ' | 'CQ' | 'FULL';

export interface MCQOption {
  id: string;
  text: string;
}

export interface MCQQuestion {
  id: string;
  type: 'MCQ';
  chapter: string;
  question: string;
  options: MCQOption[];
  correctOptionId: string;
  explanation: string;
  difficulty: 'Easy' | 'Medium' | 'Hard';
}

export interface CQQuestion {
  id: string;
  type: 'CQ';
  chapter: string;
  stem: string;
  parts: {
    a: { question: string; marks: number; label: string };
    b: { question: string; marks: number; label: string };
    c: { question: string; marks: number; label: string };
    d: { question: string; marks: number; label: string };
  };
}

export type Question = MCQQuestion | CQQuestion;

export interface ExamSession {
  id: string;
  subject: Subject;
  mode: 'Practice' | 'Exam' | 'BOARD';
  startTime: number;
  questions: Question[];
  durationMinutes: number;
  isCompleted: boolean;
  language: Language;
}

export interface GradingResult {
  questionId: string;
  obtainedMarks: number;
  maxMarks: number;
  feedback: string;
  status: 'Correct' | 'Partial' | 'Incorrect';
}

export interface SessionHistory {
  sessionId: string;
  subject: Subject;
  timestamp: number;
  score: number;
  totalMarks: number;
  accuracy: number;
  durationMinutes: number;
  mode: 'Practice' | 'Exam' | 'BOARD';
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  text: string;
  image?: string;
  timestamp: number;
}

export interface TutorSession {
  id: string;
  subject: Subject;
  messages: ChatMessage[];
  lastActive: number;
}

import React, { useState, useRef, useEffect } from 'react';
import { 
  Send, 
  Camera, 
  X, 
  Sparkles, 
  Bot, 
  User, 
  Loader2, 
  Image as ImageIcon,
  BookOpen,
  History,
  Plus,
  Trash2,
  MessageSquare
} from 'lucide-react';
import { Subject, ChatMessage, TutorSession } from '../types';
import { geminiService } from '../services/geminiService';

const AITutorView: React.FC = () => {
  const [sessions, setSessions] = useState<TutorSession[]>(() => {
    const saved = localStorage.getItem('mrab_tutor_sessions');
    return saved ? JSON.parse(saved) : [];
  });

  const [activeSessionId, setActiveSessionId] = useState<string | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [inputText, setInputText] = useState('');
  const [selectedSubject, setSelectedSubject] = useState<Subject>(Subject.BANGLA_1ST);
  const [attachedImage, setAttachedImage] = useState<string | null>(null);
  const [isTyping, setIsTyping] = useState(false);
  const [showHistory, setShowHistory] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const subjects = [
    Subject.MATH, 
    Subject.BANGLA_1ST, 
    Subject.ENGLISH_1ST, 
    Subject.ENGLISH_2ND,
    Subject.HISTORY, 
    Subject.GEOGRAPHY, 
    Subject.GENERAL_SCIENCE
  ];

  const quickPrompts = [
    { label: "এই অধ্যায়টি বুঝিয়ে বলো", text: "এই অধ্যায়ের গুরুত্বপূর্ণ অংশগুলো আমাকে বুঝিয়ে বলো।" },
    { label: "বোর্ড প্রশ্ন দেখাও", text: "এই টপিক থেকে কি ধরণের বোর্ড প্রশ্ন আসতে পারে?" },
    { label: "একটি উদাহরণ দাও", text: "এই বিষয়টি একটি বাস্তব উদাহরণ দিয়ে বুঝিয়ে বলো।" }
  ];

  // Persist sessions to localStorage
  useEffect(() => {
    localStorage.setItem('mrab_tutor_sessions', JSON.stringify(sessions));
  }, [sessions]);

  // Sync current messages to active session
  useEffect(() => {
    if (activeSessionId && messages.length > 0) {
      setSessions(prev => prev.map(s => 
        s.id === activeSessionId 
        ? { ...s, messages, lastActive: Date.now() } 
        : s
      ));
    }
  }, [messages, activeSessionId]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleStartNewChat = () => {
    setActiveSessionId(null);
    setMessages([]);
    setAttachedImage(null);
    setInputText('');
    setShowHistory(false);
  };

  const handleLoadSession = (session: TutorSession) => {
    setActiveSessionId(session.id);
    setMessages(session.messages);
    setSelectedSubject(session.subject);
    setShowHistory(false);
  };

  const handleDeleteSession = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setSessions(prev => prev.filter(s => s.id !== id));
    if (activeSessionId === id) {
      handleStartNewChat();
    }
  };

  const handleSendMessage = async (text: string = inputText, image: string | null = attachedImage) => {
    if (!text.trim() && !image) return;

    let currentSessionId = activeSessionId;

    // Create session if it doesn't exist
    if (!currentSessionId) {
      const newId = Math.random().toString(36).substring(7);
      const newSession: TutorSession = {
        id: newId,
        subject: selectedSubject,
        messages: [],
        lastActive: Date.now()
      };
      setSessions(prev => [newSession, ...prev]);
      setActiveSessionId(newId);
      currentSessionId = newId;
    }

    const userMsg: ChatMessage = {
      id: Math.random().toString(36).substring(7),
      role: 'user',
      text: text,
      image: image || undefined,
      timestamp: Date.now()
    };

    const updatedMessages = [...messages, userMsg];
    setMessages(updatedMessages);
    setInputText('');
    setAttachedImage(null);
    setIsTyping(true);

    try {
      const response = await geminiService.tutorChat(selectedSubject, text, image || undefined, updatedMessages);

      const botMsg: ChatMessage = {
        id: Math.random().toString(36).substring(7),
        role: 'model',
        text: response,
        timestamp: Date.now()
      };
      setMessages(prev => [...prev, botMsg]);
    } catch (error) {
      console.error("Tutor Error:", error);
    } finally {
      setIsTyping(false);
    }
  };

  const handleImageUpload = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      setAttachedImage(reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="max-w-6xl mx-auto h-[calc(100vh-120px)] flex gap-6 relative overflow-hidden">

      {/* Sidebar - History */}
      <div className={`
        fixed md:relative z-30 inset-y-0 left-0 w-72 bg-slate-900 border border-slate-800 rounded-[2.5rem] flex flex-col transition-all duration-300 transform
        ${showHistory ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}
        ${showHistory ? 'opacity-100' : 'opacity-0 md:opacity-100 md:w-72'}
        ${!showHistory ? 'md:hidden' : 'md:flex'}
      `}>
        <div className="p-6 border-b border-slate-800 flex items-center justify-between">
          <h3 className="text-lg font-bold text-white flex items-center gap-2">
            <History size={18} className="text-indigo-400" />
            ইতিহাস
          </h3>
          <button 
            onClick={() => setShowHistory(false)}
            className="md:hidden text-slate-500 hover:text-white"
          >
            <X size={20} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-2 custom-scrollbar">
          <button 
            onClick={handleStartNewChat}
            className="w-full flex items-center gap-3 p-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-bold transition-all mb-4 shadow-lg shadow-indigo-900/20"
          >
            <Plus size={18} />
            নতুন চ্যাট
          </button>

          {sessions.length === 0 ? (
            <div className="text-center py-10">
              <MessageSquare size={32} className="mx-auto text-slate-700 mb-2" />
              <p className="text-xs text-slate-500 font-medium px-4">আপনার কোনো পূর্ববর্তী কথোপকথন নেই।</p>
            </div>
          ) : (
            sessions.map(s => (
              <div 
                key={s.id}
                onClick={() => handleLoadSession(s)}
                className={`group flex items-start gap-3 p-4 rounded-2xl cursor-pointer border transition-all ${
                  activeSessionId === s.id 
                  ? 'bg-slate-800 border-indigo-500/50 text-white' 
                  : 'bg-slate-950 border-transparent text-slate-400 hover:bg-slate-800 hover:text-slate-200'
                }`}
              >
                <div className="shrink-0 mt-1">
                  <Bot size={16} className={activeSessionId === s.id ? 'text-indigo-400' : 'text-slate-600'} />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-xs font-bold truncate">{s.subject}</p>
                  <p className="text-[10px] text-slate-500 truncate mt-0.5">
                    {s.messages[s.messages.length - 1]?.text || 'No messages'}
                  </p>
                </div>
                <button 
                  onClick={(e) => handleDeleteSession(e, s.id)}
                  className="opacity-0 group-hover:opacity-100 p-1 text-slate-600 hover:text-red-400 transition-all"
                >
                  <Trash2 size={14} />
                </button>
              </div>
            ))
          )}
        </div>
      </div>

      {/* Main Chat Area */}
      <div className="flex-1 flex flex-col min-w-0">
        <div className="flex justify-between items-center mb-6">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setShowHistory(!showHistory)}
              className="p-3 bg-slate-900 border border-slate-800 text-slate-400 hover:text-white rounded-2xl transition-all md:flex items-center gap-2"
            >
              <History size={20} />
              <span className="hidden lg:inline text-xs font-bold">ইতিহাস</span>
            </button>
            <div>
              <h2 className="text-2xl font-bold text-white flex items-center gap-3">
                <Sparkles className="text-amber-400" />
                AI টিউটর
              </h2>
              <p className="text-slate-500 text-sm hidden sm:block">যেকোনো প্রশ্ন জিজ্ঞেস করুন অথবা ছবি পাঠান</p>
            </div>
          </div>
          <div className="flex gap-2">
            <select 
              value={selectedSubject}
              onChange={(e) => setSelectedSubject(e.target.value as Subject)}
              className="bg-slate-900 border border-slate-800 text-slate-300 text-xs font-bold rounded-xl px-4 py-2 focus:outline-none focus:border-indigo-500"
            >
              {subjects.map(s => (
                <option key={s} value={s}>{s}</option>
              ))}
            </select>
          </div>
        </div>

        <div className="flex-1 bg-slate-900/30 border border-slate-800 rounded-[2.5rem] flex flex-col overflow-hidden shadow-2xl">
          {/* Chat Messages */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar">
            {messages.length === 0 && (
              <div className="h-full flex flex-col items-center justify-center text-center p-8 space-y-6">
                <div className="w-20 h-20 bg-indigo-500/10 rounded-3xl flex items-center justify-center text-indigo-400">
                  <Bot size={48} />
                </div>
                <div>
                  <h3 className="text-xl font-bold text-white mb-2">আমি আপনার SSC ২০২৬ পার্সোনাল টিউটর</h3>
                  <p className="text-slate-500 max-w-sm mx-auto">
                    গণিত, বাংলা বা অন্য যেকোনো বিষয়ের সমস্যা সমাধান করতে আমাকে টেক্সট অথবা ছবি পাঠান।
                  </p>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 w-full max-w-2xl">
                  {quickPrompts.map((p, i) => (
                    <button 
                      key={i}
                      onClick={() => handleSendMessage(p.text)}
                      className="p-4 bg-slate-900 border border-slate-800 rounded-2xl text-xs text-slate-400 hover:text-white hover:border-indigo-500 transition-all text-left group"
                    >
                      <BookOpen size={16} className="mb-2 text-indigo-400 group-hover:scale-110 transition-transform" />
                      {p.label}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {messages.map((m) => (
              <div key={m.id} className={`flex gap-4 ${m.role === 'user' ? 'flex-row-reverse' : ''}`}>
                <div className={`w-10 h-10 rounded-2xl flex items-center justify-center shrink-0 ${
                  m.role === 'user' ? 'bg-indigo-600 shadow-lg shadow-indigo-900/20' : 'bg-slate-800 text-indigo-400 border border-slate-700'
                }`}>
                  {m.role === 'user' ? <User size={20} /> : <Bot size={20} />}
                </div>
                <div className={`max-w-[85%] space-y-2 ${m.role === 'user' ? 'text-right' : ''}`}>
                  <div className={`p-4 rounded-3xl inline-block text-left ${
                    m.role === 'user' 
                    ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-900/10' 
                    : 'bg-slate-900 border border-slate-800 text-slate-200'
                  }`}>
                    {m.image && (
                      <div className="relative group/img mb-3">
                        <img src={m.image} alt="Attachment" className="max-w-full rounded-xl border border-white/10" />
                        <div className="absolute inset-0 bg-black/40 opacity-0 group-hover/img:opacity-100 transition-opacity rounded-xl flex items-center justify-center">
                          <button onClick={() => window.open(m.image)} className="p-2 bg-white/20 backdrop-blur-md rounded-lg text-white font-bold text-xs">View Full</button>
                        </div>
                      </div>
                    )}
                    <p className="text-sm md:text-base leading-relaxed whitespace-pre-wrap">{m.text}</p>
                  </div>
                  <p className="text-[10px] text-slate-500 px-2 font-medium">
                    {new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </p>
                </div>
              </div>
            ))}

            {isTyping && (
              <div className="flex gap-4">
                <div className="w-10 h-10 rounded-2xl bg-slate-800 text-indigo-400 border border-slate-700 flex items-center justify-center animate-pulse">
                  <Bot size={20} />
                </div>
                <div className="bg-slate-900 border border-slate-800 p-4 rounded-3xl flex items-center gap-3">
                  <div className="flex gap-1">
                    <span className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
                    <span className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
                    <span className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce"></span>
                  </div>
                  <span className="text-xs text-slate-500 font-bold uppercase tracking-widest">টিউটর উত্তর লিখছেন...</span>
                </div>
              </div>
            )}
          </div>

          {/* Input Area */}
          <div className="p-4 bg-slate-900/50 border-t border-slate-800">
            {attachedImage && (
              <div className="mb-4 relative inline-block">
                <img src={attachedImage} alt="Preview" className="h-24 w-24 object-cover rounded-2xl border-2 border-indigo-500 shadow-xl" />
                <button 
                  onClick={() => setAttachedImage(null)}
                  className="absolute -top-3 -right-3 bg-red-600 text-white p-1.5 rounded-full shadow-lg hover:scale-110 transition-transform"
                >
                  <X size={14} />
                </button>
              </div>
            )}

            <div className="flex items-center gap-3">
              <input 
                type="file" 
                accept="image/*" 
                className="hidden" 
                ref={fileInputRef}
                onChange={(e) => {
                  const file = e.target.files?.[0];
                  if (file) handleImageUpload(file);
                }}
              />
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="p-4 bg-slate-800 text-slate-400 hover:text-white rounded-2xl transition-all border border-slate-700 hover:border-slate-600 group"
              >
                <Camera size={20} className="group-hover:scale-110 transition-transform" />
              </button>

              <div className="flex-1 relative">
                <input 
                  type="text"
                  value={inputText}
                  onChange={(e) => setInputText(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                  placeholder="আপনার প্রশ্ন এখানে লিখুন..."
                  className="w-full bg-slate-950 border border-slate-800 rounded-2xl pl-6 pr-14 py-4 text-slate-200 focus:outline-none focus:border-indigo-500 transition-all text-sm md:text-base shadow-inner"
                />
                <button 
                  onClick={() => handleSendMessage()}
                  disabled={isTyping || (!inputText.trim() && !attachedImage)}
                  className="absolute right-2 top-1/2 -translate-y-1/2 p-3 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl transition-all disabled:opacity-30 disabled:grayscale shadow-lg shadow-indigo-900/40"
                >
                  <Send size={20} />
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Mobile History Overlay */}
      {showHistory && (
        <div 
          className="fixed inset-0 bg-slate-950/60 backdrop-blur-sm z-20 md:hidden"
          onClick={() => setShowHistory(false)}
        />
      )}
    </div>
  );
};

