import { GoogleGenAI, Type } from "@google/genai";
import { MCQQuestion, CQQuestion, Subject, GradingResult, Language, ChatMessage } from "../types.ts";

const ai = new GoogleGenAI({apiKey: process.env.API_KEY});

const CORE_BOARD_INSTRUCTIONS = `
STRICT COMPLIANCE: Bangladesh NCTB SSC Board Pattern (Short Syllabus 2026).
QUESTION STYLES:
1. MCQs must include:
   - Simple Recall (Direct facts).
   - Multiple Completion (i, ii, iii statements; Options: A. i & ii, B. ii & iii, etc.).
   - Situation-based (Small stem followed by 2 questions).
2. Creative Questions (CQ):
   - (ক) Knowledge: Direct textbook fact.
   - (খ) Comprehension: Explain 'why' or 'how' a concept works.
   - (গ) Application: Apply textbook concept to the provided Stimulus (উদ্দীপক).
   - (ঘ) Higher Order: Critical analysis/evaluation of the situation.
`;

const SUBJECT_PROMPTS = {
  [Subject.BANGLA_1ST]: `
    - ROLE: Senior Board Examiner for Bengali 1st Paper.
    - CONTENT: Follow exactly the 18 board-selected chapters (প্রত্যুপকার, সুভা, বই পড়া, etc.).
    - CQ Style: Stimulus must reflect themes of textbooks (e.g., patriotism, humanity, nature).
    - Feedback: Focus on how to write for maximum marks (ক: ১, খ: ২, গ: ৩, ঘ: ৪).
  `,
  [Subject.ENGLISH_2ND]: `
    - ROLE: Senior English Expert for SSC Board.
    - TOPICS: Articles, Prepositions, Connectors, Right form of verbs, Narrative style, Tag questions, CV writing, Formal letters.
    - STYLE: Precise, rule-oriented explanations. Provide clear examples for grammar rules.
  `,
  [Subject.HISTORY]: `
    - CQ Stem: Use modern-day analogies to historical events. 
    - Topics: Ancient/Medieval Bengal, 1970 Elections, Liberation War.
  `,
  [Subject.MATH]: `
    - MCQ: Include property-based questions and calculation-based.
    - CQ Stem: Real-world scenario leading to equations.
  `,
  [Subject.ENGLISH_1ST]: `
    - MCQ: Synonyms, Antonyms, and inference from seen passages.
    - Writing: Formal/Informal letters, Paragraphs, Graphs/Charts.
  `
};

export const geminiService = {
  async generateMCQs(subject: Subject, chapter: string, count: number, language: Language): Promise<MCQQuestion[]> {
    const isEnglishSubject = subject === Subject.ENGLISH_1ST || subject === Subject.ENGLISH_2ND;
    const effectiveLanguage = isEnglishSubject ? 'en' : language;
    const specificPrompt = SUBJECT_PROMPTS[subject as keyof typeof SUBJECT_PROMPTS] || "";

    const langPrompt = effectiveLanguage === 'bn' 
      ? "Questions and explanations MUST be in Bengali (বাংলা ভাষা). Use standard board terminology." 
      : "Questions and explanations MUST be in English.";

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `${CORE_BOARD_INSTRUCTIONS}
      Subject: ${subject}
      Topic: ${chapter}
      ${specificPrompt}
      ACTION: Generate exactly ${count} Board-style Multiple Choice Questions (MCQs).
      STRICT RULE: DO NOT include any Creative Questions (CQ), Stimulus (উদ্দীপক), or written response parts.
      ${langPrompt}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              type: { type: Type.STRING },
              chapter: { type: Type.STRING },
              question: { type: Type.STRING },
              options: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: { id: { type: Type.STRING }, text: { type: Type.STRING } },
                  required: ["id", "text"]
                }
              },
              correctOptionId: { type: Type.STRING },
              explanation: { type: Type.STRING },
              difficulty: { type: Type.STRING }
            },
            required: ["id", "type", "chapter", "question", "options", "correctOptionId", "explanation"]
          }
        }
      }
    });

    try {
      const questions: MCQQuestion[] = JSON.parse(response.text || '[]');
      return questions.filter(q => q.type === 'MCQ').slice(0, count);
    } catch (e) {
      console.error("Failed to parse MCQs", e);
      return [];
    }
  },

  async generateCQ(subject: Subject, chapter: string, language: Language): Promise<CQQuestion | null> {
    const isEnglishSubject = subject === Subject.ENGLISH_1ST || subject === Subject.ENGLISH_2ND;
    const effectiveLanguage = isEnglishSubject ? 'en' : language;
    const specificPrompt = SUBJECT_PROMPTS[subject as keyof typeof SUBJECT_PROMPTS] || "";

    const langPrompt = effectiveLanguage === 'bn' 
      ? "Content MUST be in Bengali (বাংলা ভাষা)." 
      : "Content MUST be in English.";

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `${CORE_BOARD_INSTRUCTIONS}
      Subject: ${subject}
      Topic: ${chapter}
      ${specificPrompt}
      Generate a HIGH QUALITY Board Standard Creative Question (CQ) with a high-quality stimulus (উদ্দীপক).
      ${langPrompt}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            id: { type: Type.STRING },
            type: { type: Type.STRING },
            chapter: { type: Type.STRING },
            stem: { type: Type.STRING },
            parts: {
              type: Type.OBJECT,
              properties: {
                a: { type: Type.OBJECT, properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } } },
                b: { type: Type.OBJECT, properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } } },
                c: { type: Type.OBJECT, properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } } },
                d: { type: Type.OBJECT, properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } } }
              }
            }
          }
        }
      }
    });

    try {
      return JSON.parse(response.text || 'null');
    } catch (e) {
      console.error("Failed to parse CQ", e);
      return null;
    }
  },

  async generateFullExam(subject: Subject, language: Language): Promise<{ mcqs: MCQQuestion[], cqs: CQQuestion[] }> {
    const mcqs = await this.generateMCQs(subject, "Full Syllabus 2026", 30, language);
    const cq = await this.generateCQ(subject, "Final Prep", language);
    return { mcqs, cqs: cq ? [cq] : [] };
  },

  async gradeCQAnswer(question: CQQuestion, answers: Record<string, { text: string, image?: string }>, language: Language): Promise<GradingResult[]> {
    const isEnglishSubject = question.stem.toLowerCase().includes('english');
    const langPrompt = isEnglishSubject || language === 'en' ? "Feedback in English." : "Feedback in Bengali.";

    const parts: any[] = [{ text: `Grade this answer like a strict SSC Board Examiner. Use official marking rules. ${langPrompt}` }];
    (['a', 'b', 'c', 'd'] as const).forEach(p => {
      const ans = answers[p] || { text: '' };
      parts.push({ text: `Part ${p.toUpperCase()} (${question.parts[p]?.marks} marks): ${question.parts[p]?.question}\nStudent: ${ans.text}` });
      if (ans.image) parts.push({ inlineData: { data: ans.image.split(',')[1], mimeType: 'image/jpeg' } });
    });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: { responseMimeType: "application/json" }
    });

    try {
      return JSON.parse(response.text || '[]');
    } catch (e) {
      return [];
    }
  },

  async tutorChat(subject: Subject, message: string, image?: string, history: ChatMessage[] = []): Promise<string> {
    const isEnglishSubject = subject === Subject.ENGLISH_1ST || subject === Subject.ENGLISH_2ND;
    const specificPersona = SUBJECT_PROMPTS[subject as keyof typeof SUBJECT_PROMPTS] || "Senior expert tutor.";

    const systemInstruction = `You are MRAB AI Tutor, a senior expert for Bangladesh SSC 2026 exams.
    PERSONALITY RULES:
    ${specificPersona}
    - Explain topics simply but keep board standards.
    - If user asks about 'বাংলা ১ম পত্র', use your Senior Examiner persona.
    - If user asks about 'English 2nd Paper', focus on grammar rules and composition formats (CV, Letter).
    - Analyze any provided images (problems/handwriting) carefully.`;

    const contents = history.map(h => ({
      role: h.role,
      parts: [{ text: h.text }]
    }));

    const userParts: any[] = [{ text: `Subject: ${subject}. Question: ${message}` }];
    if (image) userParts.push({ inlineData: { data: image.split(',')[1], mimeType: 'image/jpeg' } });
    contents.push({ role: 'user', parts: userParts });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents,
      config: { systemInstruction, temperature: 0.7 }
    });

    return response.text || "I'm sorry, I could not process that. Please try again.";
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { 
  Send, 
  Camera, 
  X, 
  Sparkles, 
  Bot, 
  User, 
  Loader2, 
  Image as ImageIcon,
  BookOpen,
  History as HistoryIcon,
  Plus,
  Trash2,
  MessageSquare
} from 'lucide-react';
import { Subject, ChatMessage, TutorSession } from '../types.ts';
import { geminiService } from '../services/geminiService.ts';

const AITutorView: React.FC = () => {
  const [sessions, setSessions] = useState<TutorSession[]>(() => {
    const saved = localStorage.getItem('mrab_tutor_sessions');
    return saved ? JSON.parse(saved) : [];
  });

  const [activeSessionId, setActiveSessionId] = useState<string | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [inputText, setInputText] = useState('');
  const [selectedSubject, setSelectedSubject] = useState<Subject>(Subject.BANGLA_1ST);
  const [attachedImage, setAttachedImage] = useState<string | null>(null);
  const [isTyping, setIsTyping] = useState(false);
  const [showHistory, setShowHistory] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const subjects = [
    Subject.BANGLA_1ST, 
    Subject.BANGLA_2ND,
    Subject.ENGLISH_1ST, 
    Subject.ENGLISH_2ND,
    Subject.MATH, 
    Subject.HISTORY, 
    Subject.GEOGRAPHY, 
    Subject.GENERAL_SCIENCE,
    Subject.RELIGION,
    Subject.ICT
  ];

  const quickPrompts = [
    { label: "বোর্ড প্রশ্ন দেখাও", text: "এই টপিক থেকে কি ধরণের বোর্ড প্রশ্ন আসতে পারে?" },
    { label: "এই অধ্যায়টি বুঝিয়ে বলো", text: "এই অধ্যায়ের গুরুত্বপূর্ণ অংশগুলো আমাকে বুঝিয়ে বলো।" },
    { label: "একটি উদাহরণ দাও", text: "এই বিষয়টি একটি বাস্তব উদাহরণ দিয়ে বুঝিয়ে বলো।" }
  ];

  useEffect(() => {
    localStorage.setItem('mrab_tutor_sessions', JSON.stringify(sessions));
  }, [sessions]);

  useEffect(() => {
    if (activeSessionId && messages.length > 0) {
      setSessions(prev => prev.map(s => 
        s.id === activeSessionId 
        ? { ...s, messages, lastActive: Date.now() } 
        : s
      ));
    }
  }, [messages, activeSessionId]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleStartNewChat = () => {
    setActiveSessionId(null);
    setMessages([]);
    setAttachedImage(null);
    setInputText('');
    setShowHistory(false);
  };

  const handleLoadSession = (session: TutorSession) => {
    setActiveSessionId(session.id);
    setMessages(session.messages);
    setSelectedSubject(session.subject);
    setShowHistory(false);
  };

  const handleDeleteSession = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setSessions(prev => prev.filter(s => s.id !== id));
    if (activeSessionId === id) {
      handleStartNewChat();
    }
  };

  const handleSendMessage = async (text: string = inputText, image: string | null = attachedImage) => {
    if (!text.trim() && !image) return;

    let currentSessionId = activeSessionId;

    if (!currentSessionId) {
      const newId = Math.random().toString(36).substring(7);
      const newSession: TutorSession = {
        id: newId,
        subject: selectedSubject,
        messages: [],
        lastActive: Date.now()
      };
      setSessions(prev => [newSession, ...prev]);
      setActiveSessionId(newId);
      currentSessionId = newId;
    }

    const userMsg: ChatMessage = {
      id: Math.random().toString(36).substring(7),
      role: 'user',
      text: text,
      image: image || undefined,
      timestamp: Date.now()
    };

    const updatedMessages = [...messages, userMsg];
    setMessages(updatedMessages);
    setInputText('');
    setAttachedImage(null);
    setIsTyping(true);

    try {
      const response = await geminiService.tutorChat(selectedSubject, text, image || undefined, updatedMessages);

      const botMsg: ChatMessage = {
        id: Math.random().toString(36).substring(7),
        role: 'model',
        text: response,
        timestamp: Date.now()
      };
      setMessages(prev => [...prev, botMsg]);
    } catch (error) {
      console.error("Tutor Error:", error);
    } finally {
      setIsTyping(false);
    }
  };

  const handleImageUpload = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      setAttachedImage(reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="max-w-6xl mx-auto h-[calc(100vh-120px)] flex gap-6 relative overflow-hidden">
      {/* Sidebar - History */}
      <div className={`
        fixed md:relative z-30 inset-y-0 left-0 w-72 bg-slate-900 border border-slate-800 rounded-[2.5rem] flex flex-col transition-all duration-300 transform
        ${showHistory ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}
        ${showHistory ? 'opacity-100' : 'opacity-0 md:opacity-100 md:w-72'}
        ${!showHistory ? 'md:hidden' : 'md:flex'}
      `}>
        <div className="p-6 border-b border-slate-800 flex items-center justify-between">
          <h3 className="text-lg font-bold text-white flex items-center gap-2">
            <HistoryIcon size={18} className="text-indigo-400" />
            চ্যাট ইতিহাস
          </h3>
          <button 
            onClick={() => setShowHistory(false)}
            className="md:hidden text-slate-500 hover:text-white"
          >
            <X size={20} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-2 custom-scrollbar">
          <button 
            onClick={handleStartNewChat}
            className="w-full flex items-center gap-3 p-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-bold transition-all mb-4 shadow-lg shadow-indigo-900/20"
          >
            <Plus size={18} />
            নতুন চ্যাট
          </button>

          {sessions.length === 0 ? (
            <div className="text-center py-10">
              <MessageSquare size={32} className="mx-auto text-slate-700 mb-2" />
              <p className="text-xs text-slate-500 font-medium px-4">আপনার কোনো পূর্ববর্তী কথোপকথন নেই।</p>
            </div>
          ) : (
            sessions.map(s => (
              <div 
                key={s.id}
                onClick={() => handleLoadSession(s)}
                className={`group flex items-start gap-3 p-4 rounded-2xl cursor-pointer border transition-all ${
                  activeSessionId === s.id 
                  ? 'bg-slate-800 border-indigo-500/50 text-white' 
                  : 'bg-slate-950 border-transparent text-slate-400 hover:bg-slate-800 hover:text-slate-200'
                }`}
              >
                <div className="shrink-0 mt-1">
                  <Bot size={16} className={activeSessionId === s.id ? 'text-indigo-400' : 'text-slate-600'} />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-xs font-bold truncate">{s.subject}</p>
                  <p className="text-[10px] text-slate-500 truncate mt-0.5 italic">
                    {s.messages[s.messages.length - 1]?.text.substring(0, 30) || 'বার্তা নেই'}...
                  </p>
                </div>
                <button 
                  onClick={(e) => handleDeleteSession(e, s.id)}
                  className="opacity-0 group-hover:opacity-100 p-1 text-slate-600 hover:text-red-400 transition-all"
                >
                  <Trash2 size={14} />
                </button>
              </div>
            ))
          )}
        </div>
      </div>

      {/* Main Chat Area */}
      <div className="flex-1 flex flex-col min-w-0">
        <div className="flex justify-between items-center mb-6">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setShowHistory(!showHistory)}
              className="p-3 bg-slate-900 border border-slate-800 text-slate-400 hover:text-white rounded-2xl transition-all md:flex items-center gap-2"
            >
              <HistoryIcon size={20} />
              <span className="hidden lg:inline text-xs font-bold">ইতিহাস</span>
            </button>
            <div>
              <h2 className="text-2xl font-bold text-white flex items-center gap-3">
                <Sparkles className="text-amber-400" />
                AI টিউটর
              </h2>
              <p className="text-slate-500 text-sm hidden sm:block">যেকোনো প্রশ্ন জিজ্ঞেস করুন অথবা ছবি পাঠান</p>
            </div>
          </div>
          <div className="flex gap-2">
            <select 
              value={selectedSubject}
              onChange={(e) => setSelectedSubject(e.target.value as Subject)}
              className="bg-slate-900 border border-slate-800 text-slate-300 text-xs font-bold rounded-xl px-4 py-2 focus:outline-none focus:border-indigo-500"
            >
              {subjects.map(s => (
                <option key={s} value={s}>{s}</option>
              ))}
            </select>
          </div>
        </div>

        <div className="flex-1 bg-slate-900/30 border border-slate-800 rounded-[2.5rem] flex flex-col overflow-hidden shadow-2xl">
          {/* Chat Messages */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar">
            {messages.length === 0 && (
              <div className="h-full flex flex-col items-center justify-center text-center p-8 space-y-6">
                <div className="w-20 h-20 bg-indigo-500/10 rounded-3xl flex items-center justify-center text-indigo-400">
                  <Bot size={48} />
                </div>
                <div>
                  <h3 className="text-xl font-bold text-white mb-2">আমি আপনার SSC ২০২৬ পার্সোনাল টিউটর</h3>
                  <p className="text-slate-500 max-w-sm mx-auto">
                    আমি বাংলাদেশ বোর্ড পরীক্ষার প্রশ্নপ্রণেতা ও বিশেষজ্ঞ। আপনার যেকোনো বিষয়ের সমস্যার সমাধান দিতে আমি প্রস্তুত।
                  </p>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 w-full max-w-2xl">
                  {quickPrompts.map((p, i) => (
