import React, { useState, useRef, useEffect } from 'react';
import { ExamSession, Question, GradingResult } from '../types';
import QuestionRenderer from '../components/QuestionRenderer';
import ExamTimer from '../components/ExamTimer';
import { Send, AlertCircle, CheckCircle2, ChevronRight, ChevronLeft } from 'lucide-react';

interface ActiveExamProps {
  session: ExamSession;
  onFinish: (answers: Record<string, any>) => void;
  isGrading?: boolean;
}

const ActiveExam: React.FC<ActiveExamProps> = ({ session, onFinish, isGrading }) => {
  const [currentIdx, setCurrentIdx] = useState(0);
  const [answers, setAnswers] = useState<Record<string, any>>({});
  const [isFinishing, setIsFinishing] = useState(false);
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const handleAnswer = (val: any) => {
    setAnswers(prev => ({ ...prev, [session.questions[currentIdx].id]: val }));
  };

  const isLast = currentIdx === session.questions.length - 1;

  const handleFinishRequest = () => {
    setIsFinishing(true);
    onFinish(answers);
  };

  // Scroll active question button into view when currentIdx changes
  useEffect(() => {
    const activeBtn = scrollContainerRef.current?.children[currentIdx] as HTMLElement;
    if (activeBtn && scrollContainerRef.current) {
      const container = scrollContainerRef.current;
      const scrollLeft = activeBtn.offsetLeft - container.offsetWidth / 2 + activeBtn.offsetWidth / 2;
      container.scrollTo({ left: scrollLeft, behavior: 'smooth' });
    }
  }, [currentIdx]);

  return (
    <div className="max-w-4xl mx-auto pb-32 relative">
      {/* Fixed Sticky Header */}
      <div className="sticky top-0 z-20 bg-slate-950/80 backdrop-blur-md border-b border-slate-800 py-4 px-2 mb-8 flex justify-between items-center">
        <div className="min-w-0">
          <h2 className="text-lg md:text-xl font-bold text-white flex items-center gap-3 truncate">
            {session.subject}
            <span className="shrink-0 text-[10px] md:text-sm font-normal text-slate-400 px-3 py-1 bg-slate-900 rounded-full border border-slate-800">
              প্রশ্ন {currentIdx + 1} / {session.questions.length}
            </span>
          </h2>
        </div>
        <div className="flex items-center gap-2 md:gap-4 shrink-0">
          {session.mode === 'Exam' && (
            <ExamTimer 
              durationMinutes={session.durationMinutes} 
              onTimeUp={() => onFinish(answers)} 
            />
          )}
          <button
            onClick={handleFinishRequest}
            disabled={isGrading || isFinishing}
            className="flex items-center gap-2 px-4 md:px-6 py-2 md:py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-full font-bold text-xs md:text-sm transition-all disabled:opacity-50 shadow-lg shadow-emerald-900/20"
          >
            {isGrading ? 'মূল্যায়ন...' : 'পরীক্ষা জমা দিন'}
            <Send size={16} />
          </button>
        </div>
      </div>

      <div className="px-1">
        <QuestionRenderer
          question={session.questions[currentIdx]}
          index={currentIdx}
          answer={answers[session.questions[currentIdx].id]}
          onAnswerChange={handleAnswer}
        />
      </div>

      {/* Navigation Controls - Redesigned for Scrollability */}
      <div className="fixed bottom-6 left-1/2 -translate-x-1/2 w-[95%] max-w-4xl z-30">
        <div className="bg-slate-900/90 backdrop-blur-xl p-3 md:p-4 rounded-[2rem] border border-slate-800 shadow-2xl flex items-center gap-3 md:gap-6">
          <button
            onClick={() => setCurrentIdx(prev => Math.max(0, prev - 1))}
            disabled={currentIdx === 0}
            className="shrink-0 flex items-center justify-center w-12 h-12 bg-slate-800 text-slate-400 hover:text-white rounded-2xl disabled:opacity-20 transition-all border border-slate-700"
          >
            <ChevronLeft size={24} />
          </button>

          <div 
            ref={scrollContainerRef}
            className="flex-1 flex gap-2 overflow-x-auto no-scrollbar scroll-smooth py-1 px-1 custom-scrollbar"
            style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}
          >
            {session.questions.map((_, i) => (
              <button
                key={i}
                onClick={() => setCurrentIdx(i)}
                className={`shrink-0 w-10 h-10 rounded-xl font-bold transition-all text-sm border ${
                  currentIdx === i 
                  ? 'bg-indigo-600 text-white border-indigo-400 scale-110 shadow-lg shadow-indigo-900/40' 
                  : answers[session.questions[i].id] 
                    ? 'bg-slate-800 text-slate-300 border-slate-700' 
                    : 'bg-slate-950 text-slate-600 border-slate-800 hover:border-slate-700'
                }`}
              >
                {i + 1}
              </button>
            ))}
          </div>

          <button
            onClick={() => !isLast ? setCurrentIdx(prev => prev + 1) : handleFinishRequest()}
            className={`shrink-0 flex items-center gap-2 px-4 md:px-8 py-3 rounded-2xl font-bold transition-all whitespace-nowrap text-sm md:text-base ${
              isLast 
              ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-600/20 animate-pulse' 
              : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-lg shadow-indigo-900/20'
            }`}
          >
            <span className="hidden md:inline">{isLast ? 'জমা দিন' : 'পরবর্তী'}</span>
            <ChevronRight size={20} />
          </button>
        </div>
      </div>

      <style>{`
        .no-scrollbar::-webkit-scrollbar {
          display: none;
        }
      `}</style>
    </div>
  );
};

