      Subject: ${subject}
      Topic: ${chapter}
      ${specificPrompt}
      ACTION: Generate exactly ${count} Board-style Multiple Choice Questions (MCQs).
      STRICT RULE: DO NOT include any Creative Questions (CQ), Stimulus (উদ্দীপক), or written response parts.
      IMPORTANT: The 'type' field in the JSON must be 'MCQ'.
      ${langPrompt}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              type: { type: Type.STRING, description: "Must be 'MCQ'." },
              chapter: { type: Type.STRING },
              question: { type: Type.STRING },
              options: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: { id: { type: Type.STRING }, text: { type: Type.STRING } },
                  required: ["id", "text"]
                }
              },
              correctOptionId: { type: Type.STRING },
              explanation: { type: Type.STRING },
              difficulty: { type: Type.STRING }
            },
            required: ["id", "type", "chapter", "question", "options", "correctOptionId", "explanation"]
          }
        }
      }
    });

    try {
      const cleanedText = cleanJsonResponse(response.text);
      const questions: MCQQuestion[] = JSON.parse(cleanedText);
      // Fallback: if type is missing or wrong but it looks like an MCQ, we keep it
      return questions.map(q => ({ ...q, type: 'MCQ' as const })).slice(0, count);
    } catch (e) {
      console.error("Failed to parse MCQs", e);
      return [];
    }
  },

  async generateCQ(subject: Subject, chapter: string, language: Language): Promise<CQQuestion | null> {
    const isEnglishSubject = subject === Subject.ENGLISH_1ST || subject === Subject.ENGLISH_2ND;
    const effectiveLanguage = isEnglishSubject ? 'en' : language;
    const specificPrompt = SUBJECT_PROMPTS[subject as keyof typeof SUBJECT_PROMPTS] || "";

    const langPrompt = effectiveLanguage === 'bn' 
      ? "Content MUST be in Bengali (বাংলা ভাষা)." 
      : "Content MUST be in English.";

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `${CORE_BOARD_INSTRUCTIONS}
      Subject: ${subject}
      Topic: ${chapter}
      ${specificPrompt}
      Generate a HIGH QUALITY Board Standard Creative Question (CQ) with a high-quality stimulus (উদ্দীপক).
      ${langPrompt}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            id: { type: Type.STRING },
            type: { type: Type.STRING },
            chapter: { type: Type.STRING },
            stem: { type: Type.STRING },
            parts: {
              type: Type.OBJECT,
              properties: {
                a: { type: Type.OBJECT, properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } }, required: ["question", "marks", "label"] },
                b: { type: Type.OBJECT, properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } }, required: ["question", "marks", "label"] },
                c: { type: Type.OBJECT, properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } }, required: ["question", "marks", "label"] },
                d: { type: Type.OBJECT, properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } }, required: ["question", "marks", "label"] }
              },
              required: ["a", "b", "c", "d"]
            }
          },
          required: ["id", "type", "chapter", "stem", "parts"]
        }
      }
    });

    try {
      const cleanedText = cleanJsonResponse(response.text);
      return JSON.parse(cleanedText);
    } catch (e) {
      console.error("Failed to parse CQ", e);
      return null;
    }
  },

  async generateFullExam(subject: Subject, language: Language): Promise<{ mcqs: MCQQuestion[], cqs: CQQuestion[] }> {
    const mcqs = await this.generateMCQs(subject, "Full Syllabus 2026", 30, language);
    const cq = await this.generateCQ(subject, "Final Prep", language);
    return { mcqs, cqs: cq ? [cq] : [] };
  },

  async gradeCQAnswer(question: CQQuestion, answers: Record<string, { text: string, image?: string }>, language: Language): Promise<GradingResult[]> {
    const isEnglishSubject = question.stem.toLowerCase().includes('english');
    const langPrompt = isEnglishSubject || language === 'en' ? "Feedback in English." : "Feedback in Bengali.";

    const parts: any[] = [{ text: `Grade this answer like a strict SSC Board Examiner. Use official marking rules. ${langPrompt}` }];
    (['a', 'b', 'c', 'd'] as const).forEach(p => {
      const ans = answers[p] || { text: '' };
      parts.push({ text: `Part ${p.toUpperCase()} (${question.parts[p]?.marks} marks): ${question.parts[p]?.question}\nStudent Answer: ${ans.text}` });
      if (ans.image) parts.push({ inlineData: { data: ans.image.split(',')[1], mimeType: 'image/jpeg' } });
    });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: { 
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              questionId: { type: Type.STRING },
              obtainedMarks: { type: Type.NUMBER },
              maxMarks: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              status: { type: Type.STRING }
            },
            required: ["questionId", "obtainedMarks", "maxMarks", "feedback", "status"]
          }
        }
      }
    });

    try {
      const cleanedText = cleanJsonResponse(response.text);
      return JSON.parse(cleanedText);
    } catch (e) {
      return [];
    }
  },

  async tutorChat(subject: Subject, message: string, image?: string, history: ChatMessage[] = []): Promise<string> {
    const isEnglishSubject = subject === Subject.ENGLISH_1ST || subject === Subject.ENGLISH_2ND;
    const specificPersona = SUBJECT_PROMPTS[subject as keyof typeof SUBJECT_PROMPTS] || "Senior expert tutor.";

    const systemInstruction = `You are MRAB AI Tutor, a senior expert for Bangladesh SSC 2026 exams.
    PERSONALITY RULES:
    ${specificPersona}
    - Explain topics simply but keep board standards.
    - If user asks about 'বাংলা ১ম পত্র', use your Senior Examiner persona.
    - If user asks about 'English 2nd Paper', focus on grammar rules and composition formats (CV, Letter).
    - Analyze any provided images (problems/handwriting) carefully.`;

    const contents = history.map(h => ({
      role: h.role,
      parts: [{ text: h.text }]
    }));

    const userParts: any[] = [{ text: `Subject: ${subject}. Question: ${message}` }];
    if (image) userParts.push({ inlineData: { data: image.split(',')[1], mimeType: 'image/jpeg' } });
    contents.push({ role: 'user', parts: userParts });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents,
      config: { systemInstruction, temperature: 0.7 }
    });

    return response.text || "I'm sorry, I could not process that. Please try again.";
  }
};

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout.tsx';
import Dashboard from './views/Dashboard.tsx';
import PracticeView from './views/PracticeView.tsx';
import ActiveExam from './views/ActiveExam.tsx';
import ResultsView from './views/ResultsView.tsx';
import ExamHubView from './views/ExamHubView.tsx';
import ExamHistoryView from './views/ExamHistoryView.tsx';
import AITutorView from './views/AITutorView.tsx';
import { geminiService } from './services/geminiService.ts';
import { Subject, QuestionType, ExamSession, GradingResult, Language, UserProfile, SessionHistory, UserGoals, Department } from './types.ts';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState('dashboard');
  const [isLoading, setIsLoading] = useState(false);
  const [activeSession, setActiveSession] = useState<ExamSession | null>(null);
  const [gradingResults, setGradingResults] = useState<GradingResult[] | null>(null);
  const [sessionAnswers, setSessionAnswers] = useState<Record<string, any>>({});

  const [userProfile, setUserProfile] = useState<UserProfile>(() => {
    const saved = localStorage.getItem('mrab_profile');
    return saved ? JSON.parse(saved) : { 
      department: Department.HUMANITIES,
      goals: { topicsMastered: 20, studyHours: 50, targetAccuracy: 80 }
    };
  });

  const [sessionHistory, setSessionHistory] = useState<SessionHistory[]>(() => {
    const saved = localStorage.getItem('mrab_history');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('mrab_profile', JSON.stringify(userProfile));
  }, [userProfile]);

  useEffect(() => {
    localStorage.setItem('mrab_history', JSON.stringify(sessionHistory));
  }, [sessionHistory]);

  const startPractice = async (subject: Subject, chapter: string, type: QuestionType, count: number, language: Language) => {
    setIsLoading(true);
    try {
      let questions = [];
      if (type === 'MCQ') {
        const mcqs = await geminiService.generateMCQs(subject, chapter, count, language);
        // Case-insensitive filtering for safety
        questions = mcqs.filter(q => q.type?.toUpperCase() === 'MCQ').slice(0, count);
      } else {
        const cq = await geminiService.generateCQ(subject, chapter, language);
        if (cq && (cq.type?.toUpperCase() === 'CQ' || cq.parts)) questions = [cq];
      }

      if (questions.length > 0) {
        const newSession: ExamSession = {
          id: Math.random().toString(36).substring(7),
          subject,
          mode: 'Practice',
          startTime: Date.now(),
          questions,
          durationMinutes: type === 'MCQ' ? Math.max(5, count * 1) : 30,
          isCompleted: false,
          language
        };
        setActiveSession(newSession);
        setActiveView('active-exam');
      } else {
        alert("দুঃখিত, কোনো প্রশ্ন তৈরি করা সম্ভব হয়নি। দয়া করে আবার চেষ্টা করুন। (Failed to generate questions, please try again.)");
      }
    } catch (error) {
      console.error("Start Practice Error:", error);
      alert("একটি ত্রুটি হয়েছে। আপনার ইন্টারনেট সংযোগ যাচাই করে আবার চেষ্টা করুন।");
    } finally {
      setIsLoading(false);
    }
  };

  const startBoardExam = async (subject: Subject, language: Language) => {
    setIsLoading(true);
    try {
      const { mcqs, cqs } = await geminiService.generateFullExam(subject, language);
      const allQuestions = [...mcqs, ...cqs];

      if (allQuestions.length > 0) {
        const newSession: ExamSession = {
          id: Math.random().toString(36).substring(7),
          subject,
          mode: 'BOARD',
          startTime: Date.now(),
          questions: allQuestions,
          durationMinutes: 120,
          isCompleted: false,
          language
        };
        setActiveSession(newSession);
        setActiveView('active-exam');
      } else {
        alert("পরীক্ষার প্রশ্নপত্র লোড করা যায়নি।");
      }
    } catch (error) {
      console.error("Start Board Exam Error:", error);
      alert("ত্রুটি: বোর্ড প্রশ্নপত্র তৈরি করা সম্ভব হয়নি।");
    } finally {
      setIsLoading(false);
    }
  };

  const handleFinishExam = async (answers: Record<string, any>) => {
    if (!activeSession) return;
    setSessionAnswers(answers);
    setIsLoading(true);

    try {
      const results: GradingResult[] = [];
      for (const q of activeSession.questions) {
        if (q.type === 'MCQ') {
          const isCorrect = answers[q.id] === q.correctOptionId;
          const fb = activeSession.language === 'bn' 
            ? (isCorrect ? 'অসাধারণ! ধারণাটি পরিষ্কার।' : `সঠিক উত্তর: ${q.options.find(o => o.id === q.correctOptionId)?.text}।`)
            : (isCorrect ? 'Excellent! Concept is clear.' : `Correct answer: ${q.options.find(o => o.id === q.correctOptionId)?.text}.`);

          results.push({
            questionId: q.id,
            obtainedMarks: isCorrect ? 1 : 0,
            maxMarks: 1,
            feedback: fb,
            status: isCorrect ? 'Correct' : 'Incorrect'
          });
        } else {
          const cqResult = await geminiService.gradeCQAnswer(q, answers[q.id] || {}, activeSession.language);
          results.push(...cqResult);
        }
      }

      const obtained = results.reduce((acc, r) => acc + r.obtainedMarks, 0);
      const total = results.reduce((acc, r) => acc + r.maxMarks, 0);
      const accuracy = Math.round((obtained / total) * 100) || 0;

      const historyEntry: SessionHistory = {
        sessionId: activeSession.id,
        subject: activeSession.subject,
        timestamp: Date.now(),
        score: obtained,
        totalMarks: total,
        accuracy: accuracy,
        durationMinutes: activeSession.durationMinutes,
        mode: activeSession.mode
      };

      setSessionHistory(prev => [...prev, historyEntry]);
      setGradingResults(results);
      setActiveView('results');
    } catch (error) {
      console.error("Grading Error:", error);
      alert("মূল্যায়ন করার সময় একটি সমস্যা হয়েছে।");
    } finally {
      setIsLoading(false);
    }
  };

  const handleUpdateGoals = (newGoals: UserGoals) => {
    setUserProfile(prev => ({ ...prev, goals: newGoals }));
  };

  const renderView = () => {
    switch (activeView) {
      case 'dashboard':
        return (
          <Dashboard 
            onStartPractice={() => setActiveView('practice')} 
            onGoToExams={() => setActiveView('exams')}
            profile={userProfile}
            history={sessionHistory}
            onUpdateGoals={handleUpdateGoals}
          />
        );
      case 'practice':
        return <PracticeView onStart={startPractice} isLoading={isLoading} />;
      case 'tutor':
        return <AITutorView />;
      case 'exams':
        return <ExamHubView onStartExam={startBoardExam} onGoToHistory={() => setActiveView('exam-history')} isLoading={isLoading} />;
      case 'exam-history':
        return <ExamHistoryView history={sessionHistory} onBack={() => setActiveView('exams')} />;
      case 'active-exam':
        return activeSession ? (
          <ActiveExam session={activeSession} onFinish={handleFinishExam} isGrading={isLoading} />
        ) : null;
      case 'results':
        return activeSession && gradingResults ? (
          <ResultsView 
            questions={activeSession.questions} 
            answers={sessionAnswers}
            results={gradingResults}
            onBack={() => {
              setActiveView('dashboard');
              setActiveSession(null);
            }}
          />
        ) : null;
      default:
        return (
          <Dashboard 
            onStartPractice={() => setActiveView('practice')} 
            onGoToExams={() => setActiveView('exams')}
            profile={userProfile}
            history={sessionHistory}
            onUpdateGoals={handleUpdateGoals}
          />
        );
    }
  };

  return (
    <Layout activeView={activeView} onNavigate={setActiveView}>
      {renderView()}
    </Layout>
  );
};

export default App;

