import { GoogleGenAI, Type } from "@google/genai";
import { MCQQuestion, CQQuestion, Subject, GradingResult, Language, ChatMessage } from "../types.ts";

const ai = new GoogleGenAI({apiKey: process.env.API_KEY});

const CORE_BOARD_INSTRUCTIONS = `
STRICT COMPLIANCE: Bangladesh NCTB SSC Board Pattern (Short Syllabus 2026).
ROLE: Senior Board Question Setter & Assessment Expert.

QUESTION PRIORITIZATION (Most Important):
- Focus on HIGH-YIELD topics that have >80% probability of appearing in board exams.
- Mirror the "Core Learning Outcomes" (শিখনফল) defined by NCTB.
- Use patterns from the last 10 years of Board Exams (Dhaka, Rajshahi, etc.).
- AVOID obscure or trivial facts that are rarely tested.

QUESTION STYLES:
1. MCQs:
   - 40% Simple Recall (Direct facts from textbook).
   - 30% Multiple Completion (i, ii, iii statements).
   - 30% Situation-based (Small stem followed by 2 questions).
2. Creative Questions (CQ):
   - (ক) Knowledge: Common definitions/facts.
   - (খ) Comprehension: Core concepts often asked in "Anudhabon".
   - (গ) Application: Stimulus must be relatable to the textbook theme.
   - (ঘ) Higher Order: Comparative analysis or justification.
`;

const SUBJECT_PROMPTS = {
  [Subject.BANGLA_1ST]: `
    - Focus: Character traits in "Suva", themes of patriotism in "Kopotakkho Nod", and the struggle for independence.
    - High Probability: Questions related to 'শিক্ষা ও মনুষ্যত্ব' (values) and '৭১ এর দিনগুলি' (history).
  `,
  [Subject.ENGLISH_2ND]: `
    - Focus: "Right form of verbs", "Changing sentences" (Active/Passive, Degree), and "Narrative style".
    - High Probability: CV with cover letter for a Teacher/Manager post; Formal letters for school facilities.
  `,
  [Subject.HISTORY]: `
    - Focus: 1970 Elections, Language Movement, and the structure of the Mujibnagar Government.
    - High Probability: Comparisons between different colonial eras.
  `,
  [Subject.MATH]: `
    - Focus: Set operations, Algebraic identities, and Trigonometric ratios.
    - High Probability: Statistics (Mean, Median, Mode) and Geometry theorems involving circles.
  `,
  [Subject.ENGLISH_1ST]: `
    - Focus: Information transfer from passages, Summarizing, and Writing Paragraphs.
  `
};

/**
 * Helper to clean JSON response from potential markdown wrappers
 */
const cleanJsonResponse = (text: string | undefined): string => {
  if (!text) return '[]';
  return text.replace(/```json/g, '').replace(/```/g, '').trim();
};

export const geminiService = {
  async generateMCQs(subject: Subject, chapter: string, count: number, language: Language): Promise<MCQQuestion[]> {
    const isEnglishSubject = subject === Subject.ENGLISH_1ST || subject === Subject.ENGLISH_2ND;
    const effectiveLanguage = isEnglishSubject ? 'en' : language;
    const specificPrompt = SUBJECT_PROMPTS[subject as keyof typeof SUBJECT_PROMPTS] || "";

    const langPrompt = effectiveLanguage === 'bn' 
      ? "Questions and explanations MUST be in Bengali (বাংলা ভাষা). Use standard board terminology." 
      : "Questions and explanations MUST be in English.";

    // Check if "Full Syllabus" is requested
    const isFullSyllabus = chapter.toLowerCase().includes('full syllabus');
    const topicInstruction = isFullSyllabus 
      ? `Topic: ENTIRE SYLLABUS of ${subject}. ACTION: Select a balanced mix of questions from ALL core chapters of this subject.`
      : `Topic: ${chapter} within ${subject}.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `${CORE_BOARD_INSTRUCTIONS}
      Subject: ${subject}
      ${topicInstruction}
      ${specificPrompt}
      ACTION: Generate exactly ${count} HIGH-PROBABILITY (কমন পড়ার উপযোগী) Board-style MCQs. 
      Focus on topics students usually find difficult or that appear frequently in past papers.
      STRICT RULE: DO NOT include any Creative Questions (CQ), Stimulus (উদ্দীপক), or written response parts.
      IMPORTANT: The 'type' field in the JSON must be 'MCQ'.
      ${langPrompt}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              type: { type: Type.STRING, description: "Must be 'MCQ'." },
              chapter: { type: Type.STRING, description: "Mention which chapter this specific question belongs to." },
              question: { type: Type.STRING },
              options: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: { id: { type: Type.STRING }, text: { type: Type.STRING } },
                  required: ["id", "text"]
                }
              },
              correctOptionId: { type: Type.STRING },
              explanation: { type: Type.STRING },
              difficulty: { type: Type.STRING }
            },
            required: ["id", "type", "chapter", "question", "options", "correctOptionId", "explanation"]
          }
        }
      }
    });

    try {
      const cleanedText = cleanJsonResponse(response.text);
      const questions: MCQQuestion[] = JSON.parse(cleanedText);
      return questions.map(q => ({ ...q, type: 'MCQ' as const })).slice(0, count);
    } catch (e) {
      console.error("Failed to parse MCQs", e);
      return [];
    }
  },

  async generateCQ(subject: Subject, chapter: string, language: Language): Promise<CQQuestion | null> {
    const isEnglishSubject = subject === Subject.ENGLISH_1ST || subject === Subject.ENGLISH_2ND;
    const effectiveLanguage = isEnglishSubject ? 'en' : language;
    const specificPrompt = SUBJECT_PROMPTS[subject as keyof typeof SUBJECT_PROMPTS] || "";

    const langPrompt = effectiveLanguage === 'bn' 
      ? "Content MUST be in Bengali (বাংলা ভাষা)." 
      : "Content MUST be in English.";

    // Check if "Full Syllabus" is requested
    const isFullSyllabus = chapter.toLowerCase().includes('full syllabus');
    const topicInstruction = isFullSyllabus 
      ? `Topic: ENTIRE SYLLABUS of ${subject}. Select a stimulus that covers multiple important concepts or a core theme of the subject.`
      : `Topic: ${chapter} within ${subject}.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `${CORE_BOARD_INSTRUCTIONS}
      Subject: ${subject}
      ${topicInstruction}
      ${specificPrompt}
      Generate a HIGH-PROBABILITY Board Standard Creative Question (CQ). 
      The Stimulus (উদ্দীপক) must be of high quality and relevant to current board trends.
      ${langPrompt}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            id: { type: Type.STRING },
            type: { type: Type.STRING },
            chapter: { type: Type.STRING },
            stem: { type: Type.STRING },
            parts: {
              type: Type.OBJECT,
              properties: {
                a: { type: Type.OBJECT, properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } }, required: ["question", "marks", "label"] },
                b: { type: Type.OBJECT, properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } }, required: ["question", "marks", "label"] },
                c: { type: Type.OBJECT, properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } }, required: ["question", "marks", "label"] },
                d: { type: Type.OBJECT, properties: { question: { type: Type.STRING }, marks: { type: Type.NUMBER }, label: { type: Type.STRING } }, required: ["question", "marks", "label"] }
              },
              required: ["a", "b", "c", "d"]
            }
          },
          required: ["id", "type", "chapter", "stem", "parts"]
        }
      }
    });

    try {
      const cleanedText = cleanJsonResponse(response.text);
      return JSON.parse(cleanedText);
    } catch (e) {
      console.error("Failed to parse CQ", e);
      return null;
    }
  },

  async generateFullExam(subject: Subject, language: Language): Promise<{ mcqs: MCQQuestion[], cqs: CQQuestion[] }> {
    const mcqs = await this.generateMCQs(subject, "Full Syllabus Comprehensive", 30, language);
    const cq = await this.generateCQ(subject, "Final Probable Case", language);
    return { mcqs, cqs: cq ? [cq] : [] };
  },

  async gradeCQAnswer(question: CQQuestion, answers: Record<string, { text: string, image?: string }>, language: Language): Promise<GradingResult[]> {
    const isEnglishSubject = question.stem.toLowerCase().includes('english');
    const langPrompt = isEnglishSubject || language === 'en' ? "Feedback in English." : "Feedback in Bengali.";

    const parts: any[] = [{ text: `Grade this answer like a strict SSC Board Examiner. Use official marking rules. ${langPrompt}` }];
    (['a', 'b', 'c', 'd'] as const).forEach(p => {
      const ans = answers[p] || { text: '' };
      parts.push({ text: `Part ${p.toUpperCase()} (${question.parts[p]?.marks} marks): ${question.parts[p]?.question}\nStudent Answer: ${ans.text}` });
      if (ans.image) parts.push({ inlineData: { data: ans.image.split(',')[1], mimeType: 'image/jpeg' } });
    });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts },
      config: { 
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              questionId: { type: Type.STRING },
              obtainedMarks: { type: Type.NUMBER },
              maxMarks: { type: Type.NUMBER },
              feedback: { type: Type.STRING },
              status: { type: Type.STRING }
            },
            required: ["questionId", "obtainedMarks", "maxMarks", "feedback", "status"]
          }
        }
      }
    });

    try {
      const cleanedText = cleanJsonResponse(response.text);
      return JSON.parse(cleanedText);
    } catch (e) {
      return [];
    }
  },

  async tutorChat(subject: Subject, message: string, image?: string, history: ChatMessage[] = []): Promise<string> {
    const isEnglishSubject = subject === Subject.ENGLISH_1ST || subject === Subject.ENGLISH_2ND;
    const specificPersona = SUBJECT_PROMPTS[subject as keyof typeof SUBJECT_PROMPTS] || "Senior expert tutor.";

    const systemInstruction = `You are MRAB AI Tutor, a senior expert for Bangladesh SSC 2026 exams.
    PERSONALITY RULES:
    ${specificPersona}
    - Prioritize explaining "HIGH-YIELD" topics that are likely to come in exams.
    - If user asks about 'বাংলা ১ম পত্র', use your Senior Examiner persona.
    - If user asks about 'English 2nd Paper', focus on grammar rules and common CV/Letter formats.
    - Analyze any provided images (problems/handwriting) carefully.`;

    const contents = history.map(h => ({
      role: h.role,
      parts: [{ text: h.text }]
    }));

    const userParts: any[] = [{ text: `Subject: ${subject}. Question: ${message}` }];
    if (image) userParts.push({ inlineData: { data: image.split(',')[1], mimeType: 'image/jpeg' } });
    contents.push({ role: 'user', parts: userParts });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents,
      config: { systemInstruction, temperature: 0.7 }
    });

    return response.text || "I'm sorry, I could not process that. Please try again.";
  }
};

